        public GenericReportGenration(IEnumerable<IRepositoryWrapper> wrappers, IMapper mapper,
             IHttpContextAccessor contextAccessor,
            IRepositoryWrapper repositoryWrapper, GenericReportManager manager, ICurrentUserService currentUserService, CommonManager commonManager) : base(contextAccessor, wrappers, out repositoryWrapper)
        {
            _repositoryWrapper = repositoryWrapper;
            _currentUserService = currentUserService;
            _mapper = mapper;
            _manager = manager;
            _commonManager = commonManager;
        }

        /// <summary>
        /// This function is get the list of column name for Particular table
        /// </summary>
        /// <param name="entityTypes"></param>
        /// <returns>List of Columns</returns>
        public Dictionary<string, List<GenericReportInfrastructureDto>> GetTableColumns(List<System.Type> entityTypes, List<string> excludedProperties)
        {
            Dictionary<string, List<GenericReportInfrastructureDto>> result = new Dictionary<string, List<GenericReportInfrastructureDto>>();

            try
            {
                foreach (System.Type entityType in entityTypes)
                {
                    List<GenericReportInfrastructureDto> propInfo = new List<GenericReportInfrastructureDto>();

                    var properties = entityType.GetProperties()
                                     .Where(x => !excludedProperties.Contains(x.Name)).ToList();


                    string entityName = entityType.Name;

                    for (var i = 0; i < properties.Count; i++)
                    {
                        var propertyInfo = properties[i];
                        #region #1746 - Chris Feedback on UserDefined Report - Phase 2
                        var isIgnoreGird = Attribute.IsDefined(propertyInfo, typeof(IgnoreGridAttribute));
                        if (isIgnoreGird) continue;
                        #endregion
                        var dynamicReportDto = new GenericReportInfrastructureDto()
                        {
                            PropertyName = FirtToLower(propertyInfo.Name),
                            Type = (Attribute.IsDefined(propertyInfo, typeof(DateRangeGridAttribute))
                                        ? GridFilterType.DateRangeFilter
                                        : Attribute.IsDefined(propertyInfo, typeof(MailTo))
                                            ? GridFilterType.MailTo
                                            : Attribute.IsDefined(propertyInfo, typeof(TextTooltip))
                                                ? GridFilterType.TextTooltip
                                                : Attribute.IsDefined(propertyInfo, typeof(DateRangeGridStringAttribute))
                                                    ? GridFilterType.DateRangeFilterString
                                                    : GridFilterType.CheckBoxFilter),
                            Tab = "",
                        };

                        propInfo.Add(dynamicReportDto);
                    }

                    result[entityName] = propInfo;
                }
            }
            catch
            {

            }
            return result;
        }
        string FirtToLower(string s)
        {
            if (s != string.Empty && char.IsUpper(s[0]))
            {
                s = char.ToLower(s[0]) + s.Substring(1);
            }
            return s;
        }

        public GenericQueryResultInfrastructureDto<GenericReportDtoGrid> GetSelectedColumns(GenericReportSave dynamicReporGrid, bool isExport)
        {
            if (dynamicReporGrid != null && dynamicReporGrid.ViewMode == ReportViewMode.Disaggregated)
            {
                return DisaggregatedDynamicColumns(dynamicReporGrid, isExport);
            }
            else
            {
                return AggregatedDynamicColumns(dynamicReporGrid, isExport);
            }
        }

        public List<FilterValueDto> GetDynamicReporFilter(string propertyName, string propertyFilter, GenericReportSave dto,bool isAdmin=false)
        {
            if (dto != null && dto.ViewMode == ReportViewMode.Disaggregated)
            {
                return GetDisaggregatedDynamicFilter(propertyName, propertyFilter, dto, isAdmin);
            }
            else
            {
                return GetDynamicFilter(propertyName, propertyFilter, dto, isAdmin);
            }
        }

