        #region //SingleLevel Report
        public GenericQueryResultInfrastructureDto<GenericReportDtoGrid> DisaggregatedDynamicColumns(GenericReportSave dynamicReporGrid, bool isExport)
        {
            List<GenericReportDtoGrid> result = new List<GenericReportDtoGrid>();
            List<string> propertyName = new List<string>();

            var rtn = new GenericQueryResultInfrastructureDto<GenericReportDtoGrid>(new GenericReportRender<GenericReportDtoGrid>(_manager, _repositoryWrapper), dynamicReporGrid.DynamicReportId[0])
            {

            };
            var dynamicModel = _repositoryWrapper.GenericReportRepository.FindByCondition(x => x.Dynamicreportsid == dynamicReporGrid.DynamicReportId[0]).FirstOrDefault();
            if (dynamicModel != null)
            {

                #region //Ticket 721 Filter TSR Report Based on UK and GROUP OPCO's
                if (!string.IsNullOrEmpty(dynamicModel.Opcoid))
                {
                    var tsrOpcoList = dynamicModel.Opcoid.Split(',').Select(id => (short)int.Parse(id)).ToList();

                    if (dynamicReporGrid.Opcoid != null && dynamicReporGrid.Opcoid.Count() > 0)
                    {
                        if (dynamicReporGrid.Opcoid.Count() < tsrOpcoList.Count())
                        {
                            var sameOpcoExistis = dynamicReporGrid.Opcoid.Where(x => !tsrOpcoList.Contains(x)).ToList();
                            if (sameOpcoExistis != null && sameOpcoExistis.Count() > 0)
                                dynamicReporGrid.Opcoid = tsrOpcoList;

                        }
                        else
                            dynamicReporGrid.Opcoid = tsrOpcoList;
                    }
                    else if (dynamicReporGrid.Opcoid == null || dynamicReporGrid.Opcoid.Count() == 0)
                        dynamicReporGrid.Opcoid = tsrOpcoList; // dynamicModel.Opcoid.Split(',').Select(id => (short)int.Parse(id)).ToList();

                }
                #endregion

                propertyName = rtn.GridRender.Render.Where(x => x.Show == true).Select(x => x.PropertyName.ToString()).ToList();

                IEnumerable<GenericReportDtoGrid> dynamicProjection;
                #region //Query
                var predicateResult = DisaggregatedApplyFilter(dynamicReporGrid, _repositoryWrapper);
                var query = GetDisaggregatedQuery(predicateResult, dynamicModel.Istestnoderequired).AsQueryable();

                if (!propertyName.Contains("archived"))
                {
                    query = query.Where(x => x.Lcmengineering.Archived == false).AsQueryable();
                }
                var orderedData = query.ApplyOrdering(dynamicReporGrid, DisaggregatedDynamicColumnsMapDB(), "Modificationdate").ToList();

                #endregion


                var getLibarysIdFromQuery = orderedData.Select(x => new
                {
                    Majorsoftwarebuildsid = x.Designcomponent.Systemtype.Majorsoftwarebuildsid,
                    Majorhardwareid = x.Designcomponent.Systemtype.Systemtypesmajorhardwarebuilds.Where(s => s.Ismain && s.Majorhardware != null).FirstOrDefault().Majorhardwareid
                })?.Distinct()?.ToList();

                var majorSoftwareEntity = _repositoryWrapper.MajorSoftwareBuild
                    .FindByConditionWithDelete(x => getLibarysIdFromQuery.Select(y => y.Majorsoftwarebuildsid).Contains(x.Majorsoftwarebuildsid)).AsNoTracking().AsSplitQuery()
                     .Include(x => x.Majorswbuildsdesigncontacts).ThenInclude(x => x.Designcontact).ThenInclude(x => x.AspnetuserverticalsUser).ThenInclude(x => x.Organisation).ThenInclude(x => x.Vertical)
                  //.Includ(x => x.Majorswbuildsdesigncontacts).ThenInclude(x => x.Designcontact).ThenInclude(x => x.Aspnetuserroles).ThenInclude(x => x.Opco)  
                  .Include(x => x.Majorswbuildsdesigncontacts).ThenInclude(x => x.Designcontact).ThenInclude(x => x.Subdomainresponsible)
                  .ToList();

                var majorHardwareEntity = _repositoryWrapper.MajorHardwareBuild
                    .FindByConditionWithDelete(x => getLibarysIdFromQuery.Select(y => y.Majorhardwareid).Contains(x.Majorhardwareid)).AsNoTracking().AsSplitQuery()
                   .Include(x => x.Buildconstruction)
                .Include(x => x.Majorhwbuildsdesigncontacts).ThenInclude(x => x.Designcontact).ThenInclude(x => x.AspnetuserverticalsUser).ThenInclude(x => x.Organisation).ThenInclude(x => x.Vertical)
                   //.Includ(x => x.Majorhwbuildsdesigncontacts).ThenInclude(x => x.Designcontact).ThenInclude(x => x.Aspnetuserroles).ThenInclude(x => x.Opco)  
                   .Include(x => x.Majorhwbuildsdesigncontacts).ThenInclude(x => x.Designcontact).ThenInclude(x => x.Subdomainresponsible)
                   .Include(x => x.Orgeqpmanufacturer)
                   .ToList();



                var allOpCosFilterDto = _repositoryWrapper.OpCo.FindAll().Select(x => new FilterValueDto
                {
                    Value = x.Opcoid.ToString(),
                    Text = x.Opco
                });
                var allVerticalFilterDto = _repositoryWrapper.VerticalResponsible.FindAll().Select(x => new FilterValueDto
                {
                    Value = x.Verticalresponsibleid.ToString(),
                    Text = x.Verticalresponsible
                });
                string allVerticalForAdminRole = string.Join(",", allVerticalFilterDto.Select(x => x.Text).ToList()).ToString();
