                var location = _repositoryWrapper.Location.FindAll().Select(x => new { x.Locationid, x.Location }).ToList();
                var environment = _repositoryWrapper.Environment.FindAll().Select(x => new { x.Environmentid, x.Environment }).ToList();

                var DeploymentType = _repositoryWrapper.DeploymentType.FindAll().Select(x => new { x.Deploymenttypeid, x.Deploymenttype }).ToList();
                var OrgEqpManufacturer = _repositoryWrapper.OriginalEquipmentManufacturer.FindAll().Select(x => new { x.Orgeqpmanufacturerid, x.Originalequipmentmanufacturer }).ToList();

                rtn.TotalItems = orderedData.Count();
                if (!isExport)
