        public List<FilterValueDto> GetDisaggregatedDynamicFilter(string propertyName, string propertyFilter, GenericQueryDto dto,bool isAdmin=false)
        {
            #region //Ticket 629 Generic reports: Opco Filter dropdown has many values even though the report is only for UK Opco

            var dynamicModel = _repositoryWrapper.GenericReportRepository.FindByCondition(x => x.Dynamicreportsid
            == ((CAM.DataTransferObjects.GenericReportDto.GenericReportSave)dto).DynamicReportId[0]).FirstOrDefault();

            //if (!string.IsNullOrEmpty(getOpcoIdsFromGenericTabel.Opcoid) && ((dto.Opcoid == null) || (dto.Opcoid != null && dto.Opcoid.Count() == 0)))
            //                    dto.Opcoid = getOpcoIdsFromGenericTabel.Opcoid.Split(',').Select(id => (short)int.Parse(id)).ToList();

            #endregion

            #region //Ticket 721 Filter TSR Report Based on UK and GROUP OPCO's
            if (!string.IsNullOrEmpty(dynamicModel.Opcoid))
            {
                var tsrOpcoList = dynamicModel.Opcoid.Split(',').Select(id => (short)int.Parse(id)).ToList();

                if (dto.Opcoid != null && dto.Opcoid.Count > 0)
                {
                    if (dto.Opcoid.Count() < tsrOpcoList.Count())
                    {
                        var sameOpcoExistis = dto.Opcoid.Where(x => !tsrOpcoList.Contains(x)).ToList();
                        if (sameOpcoExistis != null && sameOpcoExistis.Count() > 0)
                            dto.Opcoid = tsrOpcoList;

                    }
                    else
                        dto.Opcoid = tsrOpcoList;

                }
                else if (dto.Opcoid != null && dto.Opcoid.Count >= 0)
                    dto.Opcoid = tsrOpcoList; // dynamicModel.Opcoid.Split(',').Select(id => (short)int.Parse(id)).ToList();

            }
            #endregion

            var predicateResult = DisaggregatedApplyFilter(dto, _repositoryWrapper);

            var query = GetDisaggregatedQuery(predicateResult);

            if (propertyName == "verticalResponsible")
            {
                var verticalFilterDto = new List<FilterValueDto>();
                var defaultItem = new FilterValueDto { Value = "yes", Text = "---" };
                foreach (var item in query)
                {
                    List<FilterValueDto> tempList = null;
                    if (item.Networkelementasplannedsubdomainspoc !=null && item.Networkelementasplannedsubdomainspoc.Count>0)
                    {
                        tempList = _commonManager.GetVerticaleFilterDto(item.Networkelementasplannedsubdomainspoc.Select(x => x.Subdomainspocid).ToList(), 0)
                                   .Select(x=>new FilterValueDto { Text=x.Text,Value=x.Value.ToString()}).ToList();
                    }
                   
                    if (tempList != null && tempList.Any() == true)
                    {
                        var secTempList = verticalFilterDto?.Any() == true ? tempList.Where(x => !verticalFilterDto.Any(y => y.Value == x.Value)) : tempList;
                        verticalFilterDto.AddRange(secTempList);
                    }
                    else if (tempList == null || tempList != null && tempList.Count() == 0)
                    {
                        if (verticalFilterDto != null && !verticalFilterDto.Any(x => x.Value == defaultItem.Value))
                        {
                            verticalFilterDto.Add(defaultItem);
                        }
                    }
                }

                if (!isAdmin && (dto.Verticalresponsible != null && dto.Verticalresponsible.Count > 0) )
                {
                    verticalFilterDto = verticalFilterDto.Where(x => dto.Verticalresponsible.Contains(x.Value.ToString())).ToList();
                }
                return verticalFilterDto;



            }

            var comSpocs = new List<FilterValueDto>();
            if (propertyName == "engineeringContactPoint")
            {
                var eduSpoc = query.SelectMany(x => x.Lcmengineering.Lcmengineeringeduspoc.Select(y => new FilterValueDto { Text = y.Eduspoc.Email, Value = y.Eduspocid.ToString() })).ToList()
                    .Concat(query.Where(x => x.Lcmengineering != null && x.Lcmengineering.Lcmengineeringeduspoc.Count() <= 0)
                                       .Select(x =>

                                          new FilterValueDto
                                          {
                                              Text = "---",
                                              Value = "yes",
                                          }
                                       )).Distinct().ToList();

                var subDomSpoc = query.SelectMany(x => x.Lcmengineering.Lcmengineeringsubdomainspoc.Select(y => new FilterValueDto { Text = y.Subdomainspoc.Email, Value = y.Subdomainspocid.ToString() })).ToList()
                    .Concat(query.Where(x => x.Lcmengineering != null && x.Lcmengineering.Lcmengineeringsubdomainspoc.Count() <= 0)
                                       .Select(x =>

                                          new FilterValueDto
                                          {
                                              Text = "---",
                                              Value = "yes",
                                          }
                                       )).Distinct().ToList();

                comSpocs = eduSpoc.Concat(subDomSpoc).DistinctBy(x => x.Value).ToList();

            }
            var systemTypeMajorHardware = query.Where(p => p.Designcomponent.Systemtype.Systemtypesmajorhardwarebuilds.Any(m =>
                       m.Ismain &&
                       m.Systemtypeid == p.Designcomponent.Systemtype.Systemtypeid &&
                       m.Deleted == false))?.Select(x => x.Designcomponent.Systemtype.Systemtypesmajorhardwarebuilds.FirstOrDefault())?.ToList();


