        /// <summary>
        /// GetSerialNumber function used to get serial number from the HW config table 
        /// </summary>
        /// <param name="opco"></param>
        /// <param name="asIsElementName"></param>
        /// <param name="_repositoryWrapper"></param>
        /// <returns>string</returns>
        private static string GetSerialNumber(string opco, string asIsElementName, IRepositoryWrapper _repositoryWrapper)
        {
            string hwElementName = string.Empty;

            if (opco != null && asIsElementName != null)
            {
                var HwConfig = _repositoryWrapper.HardwareConfiguration.FindByCondition(x => /*x.Opco == opco &&*/ x.Elementname == asIsElementName).FirstOrDefault();
                if (HwConfig != null)
                {
                    hwElementName = HwConfig.Serialnumber;
                }
            }
            return hwElementName;
        }

        /// <summary>
        /// GetHardwareModule function used to get hardware modules from the HW config table 
        /// </summary>
        /// <param name="opco"></param>
        /// <param name="asIsElementName"></param>
        /// <param name="_repositoryWrapper"></param>
        /// <returns>string</returns>
        public string GetHardwareModule(string asIsElementName, IRepositoryWrapper _repositoryWrapper)
        {
            string hardwareModule = string.Empty;

            if (asIsElementName != null && asIsElementName != "")
            {

                var HwConfig = _repositoryWrapper.HardwareConfiguration.FindByCondition(x => Convert.ToString(x.Elementname).Trim() == asIsElementName).OrderBy(x => x.Modificationdate).ToList();
                if (HwConfig != null && HwConfig.Count > 0)
                {
                    foreach (var hw in HwConfig)
                    {
                        hardwareModule += "[productNumber=" + hw.Productnumber + ":"
                                        + "productName=" + hw.Productname + ":"
                                        + "serialNumber=" + hw.Serialnumber + ":"
                                        + "unitlocation=" + hw.Unitlocation + ":"
                                        + "revision=" + hw.Revision + ":"
                                        + "hardwareType=" + hw.Hardwaretype + ":"
                                        + "vendor=" + hw.Vendor + "];";
                    }
                }
            }
            return hardwareModule;
        }
