                                   + "revision = " + HwConfig.Revision + ":"
                                   + "hardwareType = " + HwConfig.Hardwaretype + ":"
                                   + "vendor = " + HwConfig.Vendor + "];";

                }
            }
            return hardwareModule;
        }
        private static string GetLCT(string asIsElementName, IRepositoryWrapper _repositoryWrapper)
        {
            var LCT = string.Empty;

            if (asIsElementName != "" && asIsElementName != null)
            {
                var HwConfig = _repositoryWrapper.HardwareConfiguration.FindByCondition(x => x.Elementname == asIsElementName).FirstOrDefault();
