        private static string GetBundleBudgetSafe(IEnumerable<Plannedactivities> plannedActivities)
        {
            if (plannedActivities != null && plannedActivities.Any())
            {
                var firstBudgetTrackingId = plannedActivities.FirstOrDefault()?.Budgettrackingid;

                if (firstBudgetTrackingId != null)
                {
                    if (firstBudgetTrackingId.StartsWith("1-"))
                    {
                        return "Yes";
                    }
                    else if (firstBudgetTrackingId.StartsWith("0-"))
                    {
                        return "No";
                    }
                }
            }

            return string.Empty;
        }
        public string GetSoftwareVendorName(string elementName, short? oemId, IRepositoryWrapper _repositoryWrapper)
        {
            string softwareVendorName = string.Empty;
            if (!string.IsNullOrEmpty(elementName))
            {
                var softwareVendorNameEntity = _repositoryWrapper.NetworkElementAsIs.FindByCondition(x => x.Elementdeploymentname.ToLower() == elementName.ToLower() && x.Orgeqpmanufacturerid == oemId && x.Orgeqpmanufacturer.Originalequipmentmanufacturer.ToLower() == "ericsson").Include(x => x.Orgeqpmanufacturer).FirstOrDefault();
                if (softwareVendorNameEntity != null)
                {
                    softwareVendorName = softwareVendorNameEntity.Orgeqpmanufacturer?.Originalequipmentmanufacturer;
                }

            }

            return softwareVendorName;
        }

