        private string GetHardwareDetails(string attributeName, string asIsElementName, IRepositoryWrapper _repositoryWrapper)
        {
            string respectiveDetail = string.Empty;
            if (!string.IsNullOrEmpty(asIsElementName))
            {
                var HwConfig = _repositoryWrapper.HardwareConfiguration.FindByCondition(x => x.Elementname == asIsElementName).OrderBy(x => x.Modificationdate).FirstOrDefault();
                if (HwConfig != null)
                {
                    if (attributeName.ToLower() == "moduletype")
                    {
                        respectiveDetail = HwConfig.Unitlocation + "," + HwConfig.Hardwaretype;
                    }
                    else if (attributeName.ToLower() == "componentversionnumber")
                    {
                        respectiveDetail = HwConfig.Revision;
                    }
                    else if (attributeName.ToLower() == "lastcheckedtime")
                    {
                        respectiveDetail = HwConfig.Modificationdate.ToString("dd/MM/yyyy", CultureInfo.InvariantCulture);
                    }
                    else if (attributeName.ToLower() == "meserialnumber")
                    {
                        respectiveDetail = HwConfig.Serialnumber;
                    }
                    else
                    {
                        return respectiveDetail;
                    }
                }
                else
                {
                    return respectiveDetail;
                }
            }
            else
            {
                return respectiveDetail;
            }

            return respectiveDetail;
        }

        public string GetIdentificationActionForGenericReporting(Plannedactivities paentity, DateTime? EndofMaintenance)
        {
            string IdentifiedAction = string.Empty;
            var yearFromToday = DateTime.Now.AddYears(1);
            var endOfFinancialyear = new DateTime(yearFromToday.Year, 3, 31);
            DateTime targetDate = new DateTime(yearFromToday.Year, 6, 1);
            if ((EndofMaintenance != null) && ((DateTime)EndofMaintenance <= targetDate))
            {
                if (paentity != null)
                {
                    if (paentity.Plannedcompletion <= endOfFinancialyear)
                    {
                        IdentifiedAction = "Yes";
                    }
                    else
                    {
                        IdentifiedAction = "No";
                    }
                }
                else
                {
                    IdentifiedAction = "In Preparation";
                }
            }
            else
            {
                IdentifiedAction = "";
            }

            return IdentifiedAction;
        }
