        #region TCP and TCI Bundle Version For MajorSoftware Build
        public static IEnumerable<FilterValueDto> GetTcpAndTciAssignedBundleVersionOnFilterDropDown(List<Majorsoftwarebuilds> mswBuilds, int bundleType, string filterValue)
        {
            //var bundleVersionDropDownFilterDto = new FilterValueDto();

            FilterValueDto bundleVersionDropDownFilter = new FilterValueDto();

            if (mswBuilds == null) return null;

            var bundeSoftwareEntity = mswBuilds.Where(x => x.SoftwarebuildcompatibilityMajorsoftwarebuild.Count() > 0)
                .SelectMany(y => y.SoftwarebuildcompatibilityMajorsoftwarebuild.Where(x => x.Bundletype == bundleType).Select(y => y.Bundlemajorsoftwarebuild)).DistinctBy(x => x.Softwareversion);
            return bundeSoftwareEntity.ToList().Select(x =>
            {
                bundleVersionDropDownFilter = new FilterValueDto();
                if (!string.IsNullOrEmpty(filterValue) && filterValue == x.Majorsoftwarebuildsid.ToString())
                {

                    bundleVersionDropDownFilter.Text = x.Softwareversion;
                    bundleVersionDropDownFilter.Value = x.Majorsoftwarebuildsid.ToString();

                }
                else if (string.IsNullOrEmpty(filterValue))
                {
                    bundleVersionDropDownFilter.Text = x.Softwareversion;
                    bundleVersionDropDownFilter.Value = x.Majorsoftwarebuildsid.ToString();

                }
                return bundleVersionDropDownFilter;

            });


        }
        public static string BundleVersion(Majorsoftwarebuilds mswBuilds, int bundleType)
        {
            if (mswBuilds != null)

            {
                var result = mswBuilds?.SoftwarebuildcompatibilityMajorsoftwarebuild.Where(x => x.Bundletype == bundleType).Select(x => new
                {
                    //x.Bundlemajorsoftwarebuildid,
                    x.Bundlemajorsoftwarebuild.Softwareversion,
                    //x.Bundlemajorsoftwarebuild.Majorsoftwarebuildsid,
                    //x.Bundletype,
                    //x.Softwarebuildcompatibilityid
                }).ToList();

                return string.Join(",", result.Select(x => x.Softwareversion));
            }
            else return string.Empty;

        }


