        public int CountAggregatedBasedNetworkElementReleatedForGR(Lcmengineering entity, bool isLab, IRepositoryWrapper _repositoryWrapper)
        {

            if (isLab)
            {
                return entity.Elementcount ? _repositoryWrapper.NetworkElementAsPlanned.FindAll().Include(e => e.Environment)
                    .Count(s =>
                    s.Lcmengineeringid == entity.Lcmengineeringid && s.Environment.Environment.ToLower() != ConstantValueFilter.Production) : entity.Numberofnodesinlab;
            }
            else
            {

                var deployementStatusIdList = _repositoryWrapper.DeploymentStatus
                    .FindByCondition(x => ConstantValueFilter.includeDeployementStatus.Contains(
                        x.Deploymentstatus.ToLower())).Select(x => x.Deploymentstatusid).ToList();

                return entity.Elementcount ? _repositoryWrapper.NetworkElementAsPlanned.FindAll().Include(e => e.Environment)
                    .Count(s =>
                    s.Lcmengineeringid == entity.Lcmengineeringid &&
                    s.Environment.Environment.ToLower() == ConstantValueFilter.Production
                    && (deployementStatusIdList.Contains(s.Deploymentstatusid))
                     ) : entity.Numberofnodes;
            }

        }

